remarks.para:
Example usage:

BiDiDriver driver = new BiDiDriver(TimeSpan.FromSeconds(30));
driver.RegisterModule(new CustomModule(driver));  // Must be before StartAsync
await driver.StartAsync(webSocketUrl);

member.remarks:
This method never throws for a failure in an observer of ;
such a failure is routed through the observer-error pipeline, where it is governed
by .

example.code:
await using EventDataCollector<BeforeRequestSentEventArgs> collector =
    driver.Network.OnBeforeRequestSent.AddDataCollector();

await driver.BrowsingContext.NavigateAsync(navParams);

IReadOnlyList<BeforeRequestSentEventArgs> requests = collector.GetCollectedEventData();
Console.WriteLine($"Page made {requests.Count} network requests");

EventObserver<NavigationEventArgs> observer = driver.BrowsingContext.OnLoad.AddObserver(
    e => Console.WriteLine($"Loaded: {e.Url}"));
observer.StartCapturingTasks();
await driver.BrowsingContext.NavigateAsync(navParams);
Task[] tasks = await observer.WaitForCapturedTasksAsync(1, TimeSpan.FromSeconds(30));
// When tasks.Length == 1, the capture session was automatically ended.
if (tasks.Length == 1) { /* page load event received */ }

observer.StartCapturingTasks();
await driver.BrowsingContext.NavigateAsync(navParams);
Task[] tasks = await observer.WaitForCapturedTasksAsync(1, TimeSpan.FromSeconds(10));
// When tasks.Length == 1, the capture session was automatically ended.
if (tasks.Length == 1) { await Task.WhenAll(tasks); }

observer.StartCapturingTasks();
await TriggerThreeEventsAsync();
Task[] tasks = await observer.WaitForCapturedTasksAsync(3, TimeSpan.FromSeconds(10));
// When tasks.Length == count, the capture session is automatically ended.
if (tasks.Length == 3) { await Task.WhenAll(tasks); }

EventObserver<BeforeRequestSentEventArgs> observer = driver.Network.OnBeforeRequestSent.AddObserver(
    async (e) => await ProcessRequestAsync(e),
    ObservableEventHandlerOptions.RunHandlerAsynchronously);
observer.StartCapturingTasks();
await driver.BrowsingContext.NavigateAsync(navParams);
bool occurred = await observer.WaitForCapturedTasksCompleteAsync(3, TimeSpan.FromSeconds(10));
// When occurred is true, the capture session is automatically ended.
if (occurred) { /* all 3 events received and handlers completed */ }

observer.StartCapturingTasks();
await TriggerEventsAsync();
Task[] tasks = observer.GetCapturedTasks();
await Task.WhenAll(tasks);
observer.StopCapturingTasks();

member.summary:
Source-generated JSON serializer context providing AOT-compatible metadata
for all types that flow through WebDriverBiDi command serialization.


AOT consumers should set this as their TypeInfoResolver:

var options = new JsonSerializerOptions
{
    TypeInfoResolver = WebDriverBiDiJsonSerializerContext.Default,
};

example.code:
// Synchronous handler (default) - for quick in-memory work
driver.Log.OnEntryAdded.AddObserver(e => Console.WriteLine(e.Text));

// Async handler with RunHandlerAsynchronously - for I/O or long-running work
driver.Network.OnBeforeRequestSent.AddObserver(
    async (e) => await SaveRequestToFileAsync(e.Request),
    ObservableEventHandlerOptions.RunHandlerAsynchronously);

await using EventDataCollector<BeforeRequestSentEventArgs> collector =
    driver.Network.OnBeforeRequestSent.AddDataCollector();

await driver.BrowsingContext.NavigateAsync(navParams);

IReadOnlyList<BeforeRequestSentEventArgs> requests = collector.GetCollectedEventData();
Console.WriteLine($"Page made {requests.Count} network requests");

member.returns:
 if this call transitioned the command to the canceled state;
 if the command had already completed with a result, faulted, or
been canceled, in which case the existing outcome stands and this call has no effect.

member.remarks:
Valid values for this property are greater than or equal to zero (or 
for no limit). This property does not validate its value; a value outside this range is sent as-is,
and a conforming remote end rejects it when the command is executed.

para.code:
public class WebDriverBiDiEventListener : EventListener
{
    protected override void OnEventSourceCreated(EventSource source)
    {
        if (source.Name == "WebDriverBiDi")
        {
            EnableEvents(source, EventLevel.Informational);
        }
    }

    protected override void OnEventWritten(EventWrittenEventArgs eventData)
    {
        Console.WriteLine($"[{eventData.Level}] {eventData.EventName}: {eventData.Payload?[0]}");
    }
}
